#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STATIONS 101
#define MAX_TIME 601
#define INF 1000000000

int n, m, l, s, t;
int dist[MAX_STATIONS][MAX_STATIONS];
int restaurants[MAX_STATIONS];
int dp[MAX_STATIONS][MAX_TIME][MAX_STATIONS]; // dp[station][time][count] = max restaurants visited

int main() {
    while (1) {
        scanf("%d %d %d %d %d", &n, &m, &l, &s, &t);
        if (n == 0 && m == 0 && l == 0 && s == 0 && t == 0) break;

        // Initialize distances
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dist[i][j] = (i == j) ? 0 : INF;
            }
        }

        // Read edges
        for (int i = 0; i < m; i++) {
            int a, b, c;
            scanf("%d %d %d", &a, &b, &c);
            dist[a][b] = c;
            dist[b][a] = c;
        }

        // Floyd-Warshall to compute all-pairs shortest paths
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][k] < INF && dist[k][j] < INF) {
                        int nd = dist[i][k] + dist[k][j];
                        if (nd < dist[i][j]) {
                            dist[i][j] = nd;
                        }
                    }
                }
            }
        }

        // Read restaurants
        memset(restaurants, 0, sizeof(restaurants));
        for (int i = 0; i < l; i++) {
            int station, time;
            scanf("%d %d", &station, &time);
            restaurants[station] = time;
        }

        // DP initialization
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= t; j++) {
                for (int k = 0; k <= n; k++) {
                    dp[i][j][k] = -INF;
                }
            }
        }

        // Start from station s, time 0, visited 0 restaurants
        dp[s][0][0] = 0;

        int max_restaurants = 0;

        // Iterate over time
        for (int time = 0; time <= t; time++) {
            for (int station = 0; station < n; station++) {
                for (int cnt = 0; cnt <= n; cnt++) {
                    if (dp[station][time][cnt] < 0) continue;

                    // Option 1: Try to eat at current station if there's a restaurant
                    if (station != s && restaurants[station] > 0 && time + restaurants[station] <= t) {
                        int new_time = time + restaurants[station];
                        int new_cnt = cnt + 1;
                        if (new_cnt > dp[station][new_time][new_cnt]) {
                            dp[station][new_time][new_cnt] = new_cnt;
                            if (new_cnt > max_restaurants) {
                                max_restaurants = new_cnt;
                            }
                        }
                    }

                    // Option 2: Move to another station
                    for (int next = 0; next < n; next++) {
                        if (next != station && dist[station][next] < INF) {
                            int new_time = time + dist[station][next];
                            if (new_time <= t) {
                                if (dp[station][time][cnt] > dp[next][new_time][cnt]) {
                                    dp[next][new_time][cnt] = dp[station][time][cnt];
                                }
                            }
                        }
                    }
                }
            }
        }

        printf("%d\n", max_restaurants);
    }
    return 0;
}

#include <stdio.h>
