#define INF 1000000000
#define MAXN 55
#define MAXR 20

int dist[MAXN][MAXN];
int rs[MAXR], eat[MAXR];
int dp[1<<MAXR][MAXR];

int popcount(int x) {
    int c = 0;
    while(x) { c += x&1; x>>=1; }
    return c;
}

int main() {
    int N, M, R, S, T;
    while(scanf("%d %d %d %d %d", &N, &M, &R, &S, &T) == 5) {
        if(N==0 && M==0 && R==0 && S==0 && T==0) break;
        S--; // 0-indexed

        for(int i=0;i<N;i++)
            for(int j=0;j<N;j++)
                dist[i][j] = (i==j) ? 0 : INF;

        for(int i=0;i<M;i++) {
            int u,v,w;
            scanf("%d %d %d",&u,&v,&w);
            u--; v--;
            if(w < dist[u][v]) dist[u][v] = w;
            if(w < dist[v][u]) dist[v][u] = w;
        }

        // Floyd-Warshall
        for(int k=0;k<N;k++)
            for(int i=0;i<N;i++)
                for(int j=0;j<N;j++)
                    if(dist[i][k]!=INF && dist[k][j]!=INF)
                        if(dist[i][k]+dist[k][j] < dist[i][j])
                            dist[i][j] = dist[i][k]+dist[k][j];

        for(int i=0;i<R;i++) {
            scanf("%d %d",&rs[i],&eat[i]);
            rs[i]--;
        }

        // Remove restaurants at starting station
        // (can't visit them)
        // We just won't include them in valid answers

        int sz = 1<<R;
        for(int i=0;i<sz;i++)
            for(int j=0;j<R;j++)
                dp[i][j] = INF;

        for(int i=0;i<R;i++) {
            if(rs[i]==S) continue;
            if(dist[S][rs[i]] != INF)
                dp[1<<i][i] = dist[S][rs[i]] + eat[i];
        }

        int ans = 0;
        for(int mask=1;mask<sz;mask++) {
            for(int i=0;i<R;i++) {
                if(!(mask&(1<<i))) continue;
                if(dp[mask][i]==INF) continue;
                if(rs[i]!=S && dist[rs[i]][S]!=INF && dp[mask][i]+dist[rs[i]][S]<=T)
                    if(popcount(mask)>ans) ans=popcount(mask);
                for(int j=0;j<R;j++) {
                    if(mask&(1<<j)) continue;
                    if(rs[j]==S) continue;
                    if(dist[rs[i]][rs[j]]==INF) continue;
                    int nt = dp[mask][i]+dist[rs[i]][rs[j]]+eat[j];
                    if(nt < dp[mask|(1<<j)][j])
                        dp[mask|(1<<j)][j] = nt;
                }
            }
        }
        printf("%d\n",ans);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000

typedef struct {
    int to, w, next;
} Edge;

static int min_int(int a, int b) { return a < b ? a : b; }

int main(void) {
    int N, M, L, S, T;
    while (scanf("%d %d %d %d %d", &N, &M, &L, &S, &T) == 5) {
        if (N == 0 && M == 0 && L == 0 && S == 0 && T == 0) break;

        S--;  /* make 0-indexed */

        /* graph */
        Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * M));
        int *head = (int *)malloc(sizeof(int) * N);
        for (int i = 0; i < N; i++) head[i] = -1;

        int ecnt = 0;
        for (int i = 0; i < M; i++) {
            int a, b, c;
            scanf("%d %d %d", &a, &b, &c);
            a--; b--;
            edges[ecnt].to = b; edges[ecnt].w = c; edges[ecnt].next = head[a]; head[a] = ecnt++;
            edges[ecnt].to = a; edges[ecnt].w = c; edges[ecnt].next = head[b]; head[b] = ecnt++;
        }

        /* restaurants: at most one per station is assumed */
        int *eat = (int *)malloc(sizeof(int) * N);
        for (int i = 0; i < N; i++) eat[i] = -1;

        int *restStations = (int *)malloc(sizeof(int) * L);
        int realL = 0;
        for (int i = 0; i < L; i++) {
            int p, r;
            scanf("%d %d", &p, &r);
            p--;
            if (p == S) continue; /* cannot visit starting station restaurant */
            if (eat[p] == -1) {
                eat[p] = r;
                restStations[realL++] = p;
            } else if (r < eat[p]) {
                eat[p] = r; /* keep best if duplicates exist */
            }
        }

        /* Floyd-Warshall: N is small enough for this problem class */
        int *dist = (int *)malloc(sizeof(int) * N * N);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                dist[i * N + j] = (i == j ? 0 : INF);
            }
        }
        for (int v = 0; v < N; v++) {
            for (int e = head[v]; e != -1; e = edges[e].next) {
                int u = edges[e].to;
                if (edges[e].w < dist[v * N + u]) dist[v * N + u] = edges[e].w;
            }
        }
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                int dik = dist[i * N + k];
                if (dik >= INF) continue;
                for (int j = 0; j < N; j++) {
                    int nd = dik + dist[k * N + j];
                    if (nd < dist[i * N + j]) dist[i * N + j] = nd;
                }
            }
        }

        /* Keep only reachable restaurants that can be visited and return within T individually */
        int *nodes = (int *)malloc(sizeof(int) * realL);
        int *cost = (int *)malloc(sizeof(int) * realL);
        int K = 0;
        for (int i = 0; i < realL; i++) {
            int v = restStations[i];
            if (dist[S * N + v] >= INF || dist[v * N + S] >= INF) continue;
            if (dist[S * N + v] + eat[v] + dist[v * N + S] > T) continue;
            nodes[K] = v;
            cost[K] = eat[v];
            K++;
        }

        int answer = 0;

        if (K > 0) {
            int FULL = 1 << K;

            /* travel[i][j] on compressed restaurant nodes */
            int *travel = (int *)malloc(sizeof(int) * K * K);
            for (int i = 0; i < K; i++) {
                for (int j = 0; j < K; j++) {
                    travel[i * K + j] = dist[nodes[i] * N + nodes[j]];
                }
            }

            /* dp[mask][i] = minimum time to start at S, visit mask, end at restaurant i (i in mask) */
            int *dp = (int *)malloc(sizeof(int) * FULL * K);
            for (int i = 0; i < FULL * K; i++) dp[i] = INF;

            for (int i = 0; i < K; i++) {
                int d = dist[S * N + nodes[i]];
                if (d < INF) {
                    dp[(1 << i) * K + i] = d + cost[i];
                }
            }

            for (int mask = 1; mask < FULL; mask++) {
                for (int i = 0; i < K; i++) {
                    if (!(mask & (1 << i))) continue;
                    int cur = dp[mask * K + i];
                    if (cur >= INF) continue;

                    /* Can return now? */
                    if (cur + dist[nodes[i] * N + S] <= T) {
                        int cnt = __builtin_popcount((unsigned)mask);
                        if (cnt > answer) answer = cnt;
                    }

                    for (int j = 0; j < K; j++) {
                        if (mask & (1 << j)) continue;
                        int d = travel[i * K + j];
                        if (d >= INF) continue;
                        int nmask = mask | (1 << j);
                        int nv = cur + d + cost[j];
                        if (nv < dp[nmask * K + j]) dp[nmask * K + j] = nv;
                    }
                }
            }

            free(travel);
            free(dp);
        }

        printf("%d\n", answer);

        free(edges);
        free(head);
        free(eat);
        free(restStations);
        free(dist);
        free(nodes);
        free(cost);
    }
    return 0;
}

#include <iostream>
