using namespace std;

const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    while (cin >> N >> M, N) {
        vector<vector<int>> dist(N, vector<int>(N, INF));
        for (int i = 0; i < N; ++i) dist[i][i] = 0;

        for (int i = 0; i < M; ++i) {
            int u, v, t;
            cin >> u >> v >> t;
            --u; --v;
            dist[u][v] = min(dist[u][v], t);
            dist[v][u] = min(dist[v][u], t);
        }

        // Floyd-Warshall
        for (int k = 0; k < N; ++k) {
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < N; ++j) {
                    if (dist[i][k] < INF && dist[k][j] < INF) {
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                    }
                }
            }
        }

        int P;
        cin >> P;
        vector<int> t(P), l(P);
        int start = -1;
        for (int i = 0; i < P; ++i) {
            cin >> t[i] >> l[i];
            --t[i];
            if (l[i] == 0) start = i; // restaurant at starting station
        }

        // Remove starting station restaurant
        vector<int> rest_idx;
        for (int i = 0; i < P; ++i) {
            if (i != start) rest_idx.push_back(i);
        }
        int R = rest_idx.size();

        // Precompute time cost between restaurants (including start)
        // Index P = start restaurant, others are normal
        vector<vector<int>> cost(P, vector<int>(P, INF));
        for (int i = 0; i < P; ++i) {
            for (int j = 0; j < P; ++j) {
                if (i == j) {
                    cost[i][j] = 0;
                } else {
                    int u = t[i], v = t[j];
                    if (dist[u][v] < INF) {
                        cost[i][j] = dist[u][v];
                    }
                }
            }
        }

        int T;
        cin >> T;

        // DP over subsets of restaurants (excluding start)
        int max_mask = 1 << R;
        vector<vector<int>> dp(max_mask, vector<int>(R, INF));

        // Initialize from start restaurant
        for (int i = 0; i < R; ++i) {
            int idx = rest_idx[i];
            if (cost[start][idx] < INF) {
                int total = cost[start][idx] + l[idx];
                if (total <= T) {
                    dp[1 << i][i] = total;
                }
            }
        }

        int answer = 0;
        for (int mask = 0; mask < max_mask; ++mask) {
            for (int last = 0; last < R; ++last) {
                if (!(mask & (1 << last))) continue;
                if (dp[mask][last] == INF) continue;
                int cur_time = dp[mask][last];
                int cnt = __builtin_popcount(mask);
                answer = max(answer, cnt);

                // Try to return to start
                if (cur_time + cost[rest_idx[last]][start] <= T) {
                    // already counted in answer via cnt, but we can update answer
                    // answer already set above
                }

                // Try to go to another restaurant
                for (int next = 0; next < R; ++next) {
                    if (mask & (1 << next)) continue;
                    int idx_next = rest_idx[next];
                    int travel = cost[rest_idx[last]][idx_next];
                    if (travel == INF) continue;
                    int new_time = cur_time + travel + l[idx_next];
                    if (new_time <= T) {
                        int new_mask = mask | (1 << next);
                        dp[new_mask][next] = min(dp[new_mask][next], new_time);
                    }
                }
            }
        }

        cout << answer << "\n";
    }

    return 0;
}

