int main() {
    int N, M, R, S, T;
    // Read until EOF or termination condition
    while (cin >> N >> M >> R >> S >> T && (N||M||R||S||T)) {
        const int INF = 1e9;
        vector<vector<int>> dist(N, vector<int>(N, INF));
        for (int i = 0; i < N; i++) dist[i][i] = 0;

        for (int i = 0; i < M; i++) {
            int u, v, w; cin >> u >> v >> w;
            u--; v--;
            dist[u][v] = min(dist[u][v], w);
            dist[v][u] = min(dist[v][u], w);
        }

        // Floyd-Warshall
        for (int k = 0; k < N; k++)
            for (int i = 0; i < N; i++)
                for (int j = 0; j < N; j++)
                    if (dist[i][k] < INF && dist[k][j] < INF)
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

        S--; // 0-indexed

        // Read restaurants, exclude one at S
        vector<int> rstation, rtime;
        for (int i = 0; i < R; i++) {
            int st, t; cin >> st >> t; st--;
            if (st != S) {
                rstation.push_back(st);
                rtime.push_back(t);
            }
        }

        int nr = rstation.size();
        int full = 1 << nr;

        // dp[mask][i] = min time to visit restaurants in mask, currently at restaurant i
        vector<vector<int>> dp(full, vector<int>(nr, INF));

        // Initialize: visit single restaurant i from start
        for (int i = 0; i < nr; i++) {
            if (dist[S][rstation[i]] < INF) {
                dp[1<<i][i] = dist[S][rstation[i]] + rtime[i];
            }
        }

        for (int mask = 1; mask < full; mask++) {
            for (int i = 0; i < nr; i++) {
                if (!(mask & (1<<i))) continue;
                if (dp[mask][i] == INF) continue;
                // Try to go to next restaurant j
                for (int j = 0; j < nr; j++) {
                    if (mask & (1<<j)) continue;
                    if (dist[rstation[i]][rstation[j]] < INF) {
                        int nmask = mask | (1<<j);
                        int ntime = dp[mask][i] + dist[rstation[i]][rstation[j]] + rtime[j];
                        dp[nmask][j] = min(dp[nmask][j], ntime);
                    }
                }
            }
        }

        int ans = 0;
        for (int mask = 0; mask < full; mask++) {
            for (int i = 0; i < nr; i++) {
                if (!(mask & (1<<i))) continue;
                if (dp[mask][i] == INF) continue;
                if (dist[rstation[i]][S] == INF) continue;
                if (dp[mask][i] + dist[rstation[i]][S] <= T) {
                    ans = max(ans, __builtin_popcount(mask));
                }
            }
        }

        cout << ans << "\n";
    }
    return 0;
}

