static const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int N, M, L, S, T;
        cin >> N >> M >> L >> S >> T;
        if (!cin) return 0;
        if (N == 0 && M == 0 && L == 0 && S == 0 && T == 0) break;

        --S; // 0-index

        vector<vector<long long>> dist(N, vector<long long>(N, INF));
        for (int i = 0; i < N; ++i) dist[i][i] = 0;

        for (int i = 0; i < M; ++i) {
            int a, b, c;
            cin >> a >> b >> c;
            --a; --b;
            dist[a][b] = min(dist[a][b], (long long)c);
            dist[b][a] = min(dist[b][a], (long long)c);
        }

        vector<int> station(L);
        vector<long long> eat(L);
        for (int i = 0; i < L; ++i) {
            cin >> station[i] >> eat[i];
            --station[i];
        }

        // All-pairs shortest paths
        for (int k = 0; k < N; ++k) {
            for (int i = 0; i < N; ++i) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < N; ++j) {
                    if (dist[k][j] == INF) continue;
                    long long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        // Keep only restaurants not at the starting station and reachable from S and back
        vector<int> rs;
        vector<long long> cost;
        for (int i = 0; i < L; ++i) {
            if (station[i] == S) continue; // cannot visit starting station's restaurant
            if (dist[S][station[i]] == INF || dist[station[i]][S] == INF) continue;
            rs.push_back(station[i]);
            cost.push_back(eat[i]);
        }

        int K = (int)rs.size();
        if (K == 0) {
            cout << 0 << '\n';
            continue;
        }

        // Travel times among relevant restaurants and start
        vector<long long> startTo(K), backToStart(K);
        vector<vector<long long>> w(K, vector<long long>(K, INF));
        for (int i = 0; i < K; ++i) {
            startTo[i] = dist[S][rs[i]];
            backToStart[i] = dist[rs[i]][S];
            for (int j = 0; j < K; ++j) {
                w[i][j] = dist[rs[i]][rs[j]];
            }
        }

        int FULL = 1 << K;
        vector<vector<long long>> dp(FULL, vector<long long>(K, INF));

        for (int i = 0; i < K; ++i) {
            if (startTo[i] != INF) {
                dp[1 << i][i] = startTo[i] + cost[i];
            }
        }

        int ans = 0;
        for (int mask = 1; mask < FULL; ++mask) {
            int cnt = __builtin_popcount((unsigned)mask);
            for (int last = 0; last < K; ++last) {
                long long cur = dp[mask][last];
                if (cur == INF) continue;

                // Can return to start within time limit?
                if (backToStart[last] != INF && cur + backToStart[last] <= T) {
                    ans = max(ans, cnt);
                }

                // Extend to another restaurant
                for (int nxt = 0; nxt < K; ++nxt) {
                    if (mask & (1 << nxt)) continue;
                    if (w[last][nxt] == INF) continue;
                    long long nd = cur + w[last][nxt] + cost[nxt];
                    if (nd < dp[mask | (1 << nxt)][nxt]) {
                        dp[mask | (1 << nxt)][nxt] = nd;
                    }
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int N = sc.nextInt();
            int M = sc.nextInt();
            if (N == 0 && M == 0) break;

            // station graph
            int[][] dist = new int[N][N];
            for (int i = 0; i < N; i++) {
                Arrays.fill(dist[i], INF);
                dist[i][i] = 0;
            }
            for (int i = 0; i < M; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                int t = sc.nextInt();
                dist[u][v] = Math.min(dist[u][v], t);
                dist[v][u] = Math.min(dist[v][u], t);
            }

            // Floyd-Warshall for all-pairs shortest path
            for (int k = 0; k < N; k++) {
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < N; j++) {
                        if (dist[i][k] < INF && dist[k][j] < INF) {
                            dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                        }
                    }
                }
            }

            int P = sc.nextInt();
            int T = sc.nextInt();
            int S = sc.nextInt() - 1;

            int[] restaurantStation = new int[P];
            int[] eatTime = new int[P];
            for (int i = 0; i < P; i++) {
                restaurantStation[i] = sc.nextInt() - 1;
                eatTime[i] = sc.nextInt();
            }

            // DP: dp[mask][last] = minimum time to start from S, visit set 'mask' and end at 'last'
            int Ptotal = 1 << P;
            int[][] dp = new int[Ptotal][P];
            for (int mask = 0; mask < Ptotal; mask++) {
                Arrays.fill(dp[mask], INF);
            }

            // We can start from any restaurant reachable from S (excluding S itself if it were a restaurant)
            for (int i = 0; i < P; i++) {
                if (restaurantStation[i] != S) {
                    int travel = dist[S][restaurantStation[i]];
                    if (travel < INF) {
                        dp[1 << i][i] = travel + eatTime[i];
                    }
                }
            }

            // DP over subsets
            for (int mask = 1; mask < Ptotal; mask++) {
                for (int last = 0; last < P; last++) {
                    if ((mask & (1 << last)) == 0) continue;
                    if (dp[mask][last] >= INF) continue;
                    for (int next = 0; next < P; next++) {
                        if ((mask & (1 << next)) != 0) continue;
                        int travel = dist[restaurantStation[last]][restaurantStation[next]];
                        if (travel >= INF) continue;
                        int newTime = dp[mask][last] + travel + eatTime[next];
                        if (newTime < dp[mask | (1 << next)][next]) {
                            dp[mask | (1 << next)][next] = newTime;
                        }
                    }
                }
            }

            int answer = 0;
            for (int mask = 1; mask < Ptotal; mask++) {
                for (int last = 0; last < P; last++) {
                    if ((mask & (1 << last)) == 0) continue;
                    if (dp[mask][last] >= INF) continue;
                    int returnTime = dp[mask][last] + dist[restaurantStation[last]][S];
                    if (returnTime <= T) {
                        answer = Math.max(answer, Integer.bitCount(mask));
                    }
                }
            }

            System.out.println(answer);
        }
        sc.close();
    }
}

