import java.io.*;
import java.util.*;

/*
 * Maximum number of different SIRO restaurants visitable within time limit.
 *
 * Interpretation:
 * - Undirected graph of stations, weighted by travel time.
 * - Start at station S, total available time T.
 * - Restaurant i is at station ri and needs ci time to eat.
 * - Can visit each restaurant at most once, cannot visit the restaurant at S.
 * - Must return to S within total time T.
 * - Goal: maximize number of visited restaurants.
 *
 * Standard approach:
 * 1) Compute shortest distances between all relevant nodes:
 *    start + restaurant stations.
 *    We run Dijkstra from each relevant node over the full graph.
 * 2) Reduce to a prize-collecting TSP-like DP on restaurants:
 *    dp[mask][i] = minimum time to start at S, visit restaurants in mask,
 *                  and end at restaurant i (having eaten there).
 * 3) For each state, check whether returning to S fits in T.
 *
 * This is feasible when the number of restaurants is small/moderate,
 * which is the intended constraint pattern for this classic bitmask DP task.
 *
 * Input format assumed:
 * Multiple datasets.
 * Each dataset:
 *   N M L S T
 *   M lines: a b d
 *   L lines: r c
 * Ends with a line of five zeros.
 *
 * Stations are assumed 1-indexed in input.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(int src, List<Edge>[] g) {
        int n = g.length;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[src] = 0;
        pq.add(new Node(src, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            long nL = fs.nextLong();
            if (nL == Long.MIN_VALUE) break;

            int N = (int) nL;
            int M = fs.nextInt();
            int L = fs.nextInt();
            int S = fs.nextInt() - 1;
            long T = fs.nextLong();

            if (N == 0 && M == 0 && L == 0 && S == -1 && T == 0) break;

            List<Edge>[] g = new ArrayList[N];
            for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < M; i++) {
                int a = fs.nextInt() - 1;
                int b = fs.nextInt() - 1;
                long d = fs.nextLong();
                g[a].add(new Edge(b, d));
                g[b].add(new Edge(a, d));
            }

            // Read restaurants; exclude those at start station.
            ArrayList<Integer> restStationList = new ArrayList<>();
            ArrayList<Long> eatTimeList = new ArrayList<>();
            for (int i = 0; i < L; i++) {
                int r = fs.nextInt() - 1;
                long c = fs.nextLong();
                if (r == S) continue; // cannot visit restaurant at the starting station
                restStationList.add(r);
                eatTimeList.add(c);
            }

            int R = restStationList.size();

            if (R == 0) {
                out.append(0).append('\n');
                continue;
            }

            int[] restStation = new int[R];
            long[] eat = new long[R];
            for (int i = 0; i < R; i++) {
                restStation[i] = restStationList.get(i);
                eat[i] = eatTimeList.get(i);
            }

            // Relevant nodes: start + each restaurant station
            int[] relevant = new int[R + 1];
            relevant[0] = S;
            for (int i = 0; i < R; i++) relevant[i + 1] = restStation[i];

            long[][] distRelevant = new long[R + 1][];
            for (int i = 0; i <= R; i++) {
                distRelevant[i] = dijkstra(relevant[i], g);
            }

            long[] distStartToRest = new long[R];
            long[] distRestToStart = new long[R];
            long[][] distRestToRest = new long[R][R];

            for (int i = 0; i < R; i++) {
                distStartToRest[i] = distRelevant[0][restStation[i]];
                distRestToStart[i] = distRelevant[i + 1][S];
            }
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < R; j++) {
                    distRestToRest[i][j] = distRelevant[i + 1][restStation[j]];
                }
            }

            int maxMask = 1 << R;
            long[][] dp = new long[maxMask][R];
            for (int i = 0; i < maxMask; i++) Arrays.fill(dp[i], INF);

            for (int i = 0; i < R; i++) {
                if (distStartToRest[i] < INF) {
                    dp[1 << i][i] = distStartToRest[i] + eat[i];
                }
            }

            int answer = 0;

            for (int mask = 1; mask < maxMask; mask++) {
                int cnt = Integer.bitCount(mask);
                for (int last = 0; last < R; last++) {
                    long cur = dp[mask][last];
                    if (cur >= INF) continue;

                    if (distRestToStart[last] < INF && cur + distRestToStart[last] <= T) {
                        if (cnt > answer) answer = cnt;
                    }

                    for (int nxt = 0; nxt < R; nxt++) {
                        if ((mask & (1 << nxt)) != 0) continue;
                        long move = distRestToRest[last][nxt];
                        if (move >= INF) continue;
                        int nmask = mask | (1 << nxt);
                        long nd = cur + move + eat[nxt];
                        if (nd < dp[nmask][nxt]) {
                            dp[nmask][nxt] = nd;
                        }
                    }
                }
            }

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}

