import sys

INF = 10**18

def solve_one(n, m, l, s, edges, ramen):
    # Floyd-Warshall for all-pairs shortest paths
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for a, b, c in edges:
        if c < dist[a][b]:
            dist[a][b] = dist[b][a] = c

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            nd_base = dik
            for j in range(n):
                v = nd_base + dk[j]
                if v < di[j]:
                    di[j] = v

    # Candidate restaurants excluding start station and unreachable ones
    cand_station = []
    eat = []
    for i in range(n):
        if i == s:
            continue
        if ramen[i] <= 0:
            continue
        if dist[s][i] == INF or dist[i][s] == INF:
            continue
        cand_station.append(i)
        eat.append(ramen[i])

    k = len(cand_station)
    if k == 0:
        return 0

    # Cost to go from start to restaurant i, eat there
    start_cost = [dist[s][cand_station[i]] + eat[i] for i in range(k)]
    # Cost to return from restaurant i to start
    back_cost = [dist[cand_station[i]][s] for i in range(k)]
    # Cost to go from restaurant i to restaurant j, then eat at j
    move_cost = [[0] * k for _ in range(k)]
    for i in range(k):
        u = cand_station[i]
        for j in range(k):
            v = cand_station[j]
            move_cost[i][j] = dist[u][v] + eat[j]

    # Bitmask DP:
    # dp[mask][i] = minimum time to start at s, visit exactly mask, end at i (having eaten there)
    size = 1 << k
    dp = [[INF] * k for _ in range(size)]

    for i in range(k):
        if start_cost[i] <= l:
            dp[1 << i][i] = start_cost[i]

    ans = 0
    for mask in range(size):
        cnt = mask.bit_count()
        for i in range(k):
            cur = dp[mask][i]
            if cur == INF:
                continue
            if cur + back_cost[i] <= l and cnt > ans:
                ans = cnt
            # Try visiting another restaurant
            for j in range(k):
                if (mask >> j) & 1:
                    continue
                nmask = mask | (1 << j)
                nv = cur + move_cost[i][j]
                if nv < dp[nmask][j] and nv <= l:
                    dp[nmask][j] = nv

    return ans

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    out = []
    while True:
        try:
            n = int(next(it))
            m = int(next(it))
            l = int(next(it))
            s = int(next(it)) - 1
        except StopIteration:
            break

        if n == 0 and m == 0 and l == 0 and s == -1:
            break

        edges = []
        for _ in range(m):
            a = int(next(it)) - 1
            b = int(next(it)) - 1
            c = int(next(it))
            edges.append((a, b, c))

        ramen = [0] * n
        for i in range(n):
            ramen[i] = int(next(it))

        out.append(str(solve_one(n, m, l, s, edges, ramen)))

    sys.stdout.write("\n".join(out))

